export function PushNotification({
  appName = "{{appName}}",
  message = "{{message}}",
  platform = "{{platform}}",
  accent = "{{accent}}",
  showActions = {{showActions}},
}) {
  const mobile = platform === "mobile";
  return (
    <div role="status" style={{ display: "flex", gap: 10, width: 320, boxSizing: "border-box",
      padding: mobile ? 14 : 12, background: "#FAF7F2", color: "#241430",
      borderRadius: mobile ? 18 : 10, boxShadow: "0 6px 20px rgba(36,20,48,.22)", fontSize: 13 }}>
      <span aria-hidden="true" style={{ width: 30, height: 30, borderRadius: mobile ? "50%" : 8, background: accent, flexShrink: 0 }} />
      <div style={{ flex: 1 }}>
        <p style={{ margin: "0 0 2px", display: "flex", justifyContent: "space-between", fontWeight: 600, fontSize: 12, textTransform: "uppercase", letterSpacing: .03, color: "#24143099" }}>
          {appName} <time style={{ textTransform: "none", fontWeight: 400 }} dateTime="2026-08-18T09:14">now</time>
        </p>
        <p style={{ margin: 0 }}>{message}</p>
        {showActions && (
          <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
            <button type="button" style={{ border: "1px solid #24143030", background: "transparent", borderRadius: 6, padding: "4px 10px", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Open</button>
            <button type="button" style={{ border: "1px solid #24143030", background: "transparent", borderRadius: 6, padding: "4px 10px", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Dismiss</button>
          </div>
        )}
      </div>
    </div>
  );
}
